#!/usr/bin/env node
/*
 * Regenerates certificates-data.js from whatever is currently in /Certificates.
 *
 * Run this after adding, removing, or renaming a file in /Certificates:
 *   node scripts/build-certificates.js
 *
 * Both index.html (recent-10 carousel) and certificates.html (full explorer
 * table) read from the single generated file at runtime, so they can never
 * drift out of sync with each other or with the folder.
 *
 * Certificates are previewed as images (PNG/JPG) — PDFs don't render
 * reliably inline. Files are paired up by normalized base name (trimmed,
 * collapsed whitespace, case-insensitive), so "Foo.png" and "Foo .pdf"
 * still match. When a PNG/JPG has a matching PDF, the PDF becomes the
 * download target shown next to the preview.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const CERT_DIR = path.join(ROOT, 'Certificates');
const OUT_FILE = path.join(ROOT, 'certificates-data.js');

const IMAGE_EXTS = ['.png', '.jpg', '.jpeg'];

const TYPE_LABELS = {
  '.pdf': 'PDF Document',
  '.jpg': 'JPG Image',
  '.jpeg': 'JPG Image',
  '.png': 'PNG Image',
};

function cleanTitle(base) {
  let title = base;
  title = title.replace(/^Mason\s+Todd\s+Clement\s*-\s*Certificate\s*-\s*/i, '');
  title = title.replace(/^Mason\s+Clement\s*-\s*Certificate\s*-\s*/i, '');
  // fallback in case a file doesn't have "Certificate" right after the name
  title = title.replace(/^Mason\s+Todd\s+Clement\s*-\s*/i, '');
  title = title.replace(/^Mason\s+Clement\s*-\s*/i, '');
  // the name prefix is gone in newer exports, but "Certificate - " still leads
  title = title.replace(/^Certificate\s*-\s*/i, '');
  return title.trim();
}

function normalizeKey(base) {
  return base.trim().replace(/\s+/g, ' ').toLowerCase();
}

function formatDate(d) {
  return d.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

function formatSize(bytes) {
  const kb = bytes / 1024;
  if (kb < 1024) return `${Math.round(kb)} KB`;
  return `${(kb / 1024).toFixed(1)} MB`;
}

function build() {
  if (!fs.existsSync(CERT_DIR)) {
    throw new Error(`Certificates folder not found at ${CERT_DIR}`);
  }

  const files = fs
    .readdirSync(CERT_DIR)
    .filter((name) => !name.startsWith('.'));

  // Group files by normalized base name so "Foo.png" / "Foo .pdf" / "foo.PDF"
  // all land in the same bucket regardless of trailing spaces or casing.
  const groups = new Map();
  for (const name of files) {
    const ext = path.extname(name).toLowerCase();
    const base = name.slice(0, name.length - ext.length);
    const key = normalizeKey(base);

    if (!groups.has(key)) groups.set(key, { base, byExt: {} });
    const group = groups.get(key);
    group.byExt[ext] = name;
    // prefer the image file's casing/spacing for the display title
    if (IMAGE_EXTS.includes(ext)) group.base = base;
  }

  const items = [];
  const warnings = [];

  for (const group of groups.values()) {
    const imageExt = IMAGE_EXTS.find((ext) => group.byExt[ext]);
    const pdfFile = group.byExt['.pdf'] || null;
    const previewFile = imageExt ? group.byExt[imageExt] : pdfFile;
    if (!previewFile) continue;

    if (imageExt && !pdfFile) {
      warnings.push(`No matching PDF for "${previewFile}" — download button will be hidden.`);
    }
    if (!imageExt && pdfFile) {
      warnings.push(`"${pdfFile}" has no PNG/JPG preview — it'll still be embedded as a PDF, which may not display for all visitors.`);
    }

    const full = path.join(CERT_DIR, previewFile);
    const stat = fs.statSync(full);
    const ext = imageExt || '.pdf';

    items.push({
      file: previewFile,
      pdfFile,
      title: cleanTitle(group.base),
      type: TYPE_LABELS[ext] || `${ext.replace('.', '').toUpperCase()} File`,
      ext,
      date: formatDate(stat.mtime),
      mtimeMs: Math.round(stat.mtimeMs),
      size: formatSize(stat.size),
    });
  }

  items.sort((a, b) => b.mtimeMs - a.mtimeMs);

  const header =
    '/* AUTO-GENERATED by scripts/build-certificates.js — do not edit by hand.\n' +
    '   Re-run `node scripts/build-certificates.js` after changing /Certificates. */\n';
  const body = `window.CERTIFICATES = ${JSON.stringify(items, null, 2)};\n`;

  fs.writeFileSync(OUT_FILE, header + body);
  console.log(`Wrote ${items.length} certificates to ${path.relative(ROOT, OUT_FILE)}`);
  if (warnings.length) {
    console.log(`\n${warnings.length} naming mismatch(es) to check:`);
    warnings.forEach((w) => console.log(`  - ${w}`));
  }
}

build();
